function initImaging() {
  var film = $("#xray-film");
  var body = $("#xray-body");
  var incoming = $("#xray-incoming");
  var stopped = $("#xray-stopped-bone");
  var fleshRays = $("#xray-through-flesh");
  var airRays = $("#xray-through-air");
  var underBone = $("#film-under-bone");
  var underFlesh = $("#film-under-flesh");
  if (!film) return;
  function opacity(el, value) {
    if (el) el.setAttribute("opacity", String(value));
  }
  function show(kind) {
    if (kind === "air") {
      opacity(body, 0);
      opacity(incoming, 0);
      opacity(stopped, 0);
      opacity(fleshRays, 0);
      opacity(airRays, 1);
      film.setAttribute("fill", "#1c1812");
      opacity(underBone, 0);
      opacity(underFlesh, 0);
    } else if (kind === "bone") {
      opacity(body, 1);
      opacity(incoming, 1);
      opacity(stopped, 1);
      opacity(fleshRays, 0.18);
      opacity(airRays, 0);
      film.setAttribute("fill", "#3d3426");
      opacity(underBone, 1);
      opacity(underFlesh, 0.35);
    } else {
      opacity(body, 1);
      opacity(incoming, 1);
      opacity(stopped, 1);
      opacity(fleshRays, 1);
      opacity(airRays, 0);
      film.setAttribute("fill", "#3d3426");
      opacity(underBone, 1);
      opacity(underFlesh, 1);
    }
  }
  $all("[data-tissue]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      show(btn.getAttribute("data-tissue"));
    });
  });
  show("flesh");
}

input.new_string:
function initImaging() {
  var host = $("#imaging-vis");
  if (!host) return;
  var rays = $all("[data-xray]", host);
  var filmFlesh = $("#film-under-flesh");
  var reduced = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var t0 = performance.now();
  var lengths = rays.map(function (ray) {
    try {
      return ray.getTotalLength();
    } catch (err) {
      return 140;
    }
  });
  function apply(sec) {
    rays.forEach(function (ray, i) {
      var len = lengths[i];
      var dur = 0.5 + len / 260;
      var u = reduced ? 1 : Math.max(0, Math.min(1, sec / dur));
      ray.style.strokeDasharray = String(len);
      ray.style.strokeDashoffset = String(len * (1 - u));
    });
    if (filmFlesh) {
      var develop = reduced ? 1 : Math.max(0, Math.min(1, (sec - 0.65) / 0.45));
      var r = Math.round(244 - develop * 218);
      var g = Math.round(239 - develop * 217);
      var b = Math.round(224 - develop * 208);
      filmFlesh.setAttribute("fill", "rgb(" + r + "," + g + "," + b + ")");
    }
  }
  host.addEventListener("notes-replay", function () {
    t0 = performance.now();
  });
  function frame(now) {
    apply((now - t0) / 1000);
    requestAnimationFrame(frame);
  }
  apply(reduced ? 8 : 0);
  requestAnimationFrame(frame);
}

