  var electron = ball(0.12, 0x2a62a8);
  electron.position.copy(argonHome);
  gfx.scene.add(wall, wire, windowDisk, rim, argon, electron);
  var winAnchor = new THREE.Vector3(-3.2, 1.35, 0);
