    var bPos = new THREE.Vector3(lerp(-3.9, 2.6, u), lerp(0, -1.7, Math.pow(u, 1.35)), 0);
    var gPos = new THREE.Vector3(lerp(-3.9, 4.2, u), 0, 0);
