var wavePositions = new Float32Array(53 * 3);
var waveGeom = new THREE.BufferGeometry();
waveGeom.setAttribute("position", new THREE.BufferAttribute(wavePositions, 3));
var waveMesh = new THREE.Line(waveGeom, goldMat);
