function rebuildWave(phase) {
  var i;
  for (i = 0; i <= 52; i += 1) {
    var x = -5.25 + i * 0.095;
    var y = 0.58 * Math.sin(i * 0.4 - phase);
    wavePositions[i * 3] = x;
    wavePositions[i * 3 + 1] = y;
    wavePositions[i * 3 + 2] = 0;
  }
  waveGeom.attributes.position.needsUpdate = true;
  waveGeom.computeBoundingSphere();
}

