function rebuildWave(phase) {
  var pts = [];
  var i;
  for (i = 0; i <= 52; i += 1) {
    var x = -5.25 + i * 0.095;
    var y = 0.58 * Math.sin(i * 0.4 - phase);
    pts.push(new THREE.Vector3(x, y, 0));
  }
